import re
import zipfile
from collections import Counter
from datetime import datetime
from email.utils import parsedate_to_datetime
from pathlib import Path
from xml.etree import ElementTree as ET

import matplotlib.pyplot as plt


INPUT_XLSX = Path("Student_0000000000.xlsx")
OUTPUT_DIR = Path("sports_news_visualizations")


def read_inline_xlsx(path):
    """Read the simple inline-string xlsx file generated by sports_news_spider.py."""
    namespace = {"x": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
    with zipfile.ZipFile(path) as archive:
        sheet_xml = archive.read("xl/worksheets/sheet1.xml")

    root = ET.fromstring(sheet_xml)
    rows = []
    for row in root.findall(".//x:sheetData/x:row", namespace):
        values = []
        for cell in row.findall("x:c", namespace):
            text_node = cell.find(".//x:t", namespace)
            values.append(text_node.text if text_node is not None and text_node.text else "")
        rows.append(values)

    headers = rows[0]
    return [dict(zip(headers, row)) for row in rows[1:]]


def parse_news_time(value):
    try:
        return parsedate_to_datetime(value)
    except Exception:
        return None


def infer_sport_type(row):
    text = f"{row.get('标题', '')} {row.get('链接', '')}".lower()
    rules = [
        ("NHL/冰球", ["nhl", "hurricanes", "canadiens", "stanley", "avalanche"]),
        ("NBA/篮球", ["nba", "wnba", "thunder", "draft lottery", "basketball"]),
        ("MLB/棒球", ["mlb", "phillies", "baez", "baseball"]),
        ("足球", ["soccer", "world cup", "usmnt", "pulisic", "fifa"]),
        ("NFL/橄榄球", ["nfl", "broncos", "football", "quarterbacks"]),
        ("NCAA/大学体育", ["college", "ncaa", "sec", "big ten", "softball"]),
        ("网球", ["tennis", "rafael", "french open"]),
    ]
    for label, keywords in rules:
        if any(keyword in text for keyword in keywords):
            return label
    return "其他"


def content_length(row):
    return len(row.get("内容", ""))


def setup_chinese_font():
    plt.rcParams["font.sans-serif"] = [
        "Microsoft YaHei",
        "SimHei",
        "Arial Unicode MS",
        "DejaVu Sans",
    ]
    plt.rcParams["axes.unicode_minus"] = False


def save_sport_type_chart(rows):
    counts = Counter(infer_sport_type(row) for row in rows)
    labels, values = zip(*counts.most_common())

    plt.figure(figsize=(10, 6))
    bars = plt.bar(labels, values, color="#3b82f6")
    plt.title("30条体育新闻的项目类别分布")
    plt.xlabel("项目类别")
    plt.ylabel("新闻数量")
    plt.xticks(rotation=25, ha="right")
    for bar, value in zip(bars, values):
        plt.text(bar.get_x() + bar.get_width() / 2, value + 0.1, str(value), ha="center")
    plt.tight_layout()
    output = OUTPUT_DIR / "图1_体育新闻类别分布.png"
    plt.savefig(output, dpi=180)
    plt.close()
    return output


def save_content_length_chart(rows):
    lengths = [content_length(row) for row in rows]
    indexes = list(range(1, len(lengths) + 1))
    average = sum(lengths) / len(lengths)

    plt.figure(figsize=(11, 6))
    plt.bar(indexes, lengths, color="#10b981")
    plt.axhline(average, color="#ef4444", linestyle="--", linewidth=1.5, label=f"平均长度：{average:.0f} 字符")
    plt.title("30条体育新闻正文长度对比")
    plt.xlabel("新闻序号")
    plt.ylabel("正文长度（字符数）")
    plt.legend()
    plt.tight_layout()
    output = OUTPUT_DIR / "图2_正文长度对比.png"
    plt.savefig(output, dpi=180)
    plt.close()
    return output


def save_time_distribution_chart(rows):
    times = [parse_news_time(row.get("时间", "")) for row in rows]
    hours = [dt.hour for dt in times if dt is not None]
    counts = Counter(hours)
    labels = list(range(24))
    values = [counts.get(hour, 0) for hour in labels]

    plt.figure(figsize=(11, 6))
    plt.plot(labels, values, marker="o", color="#f97316", linewidth=2)
    plt.fill_between(labels, values, color="#fed7aa", alpha=0.45)
    plt.title("体育新闻发布时间小时分布")
    plt.xlabel("发布时间（小时）")
    plt.ylabel("新闻数量")
    plt.xticks(range(0, 24, 2))
    plt.grid(axis="y", alpha=0.25)
    plt.tight_layout()
    output = OUTPUT_DIR / "图3_发布时间小时分布.png"
    plt.savefig(output, dpi=180)
    plt.close()
    return output


def save_top_keywords_chart(rows):
    stopwords = {
        "the",
        "and",
        "from",
        "with",
        "for",
        "who",
        "are",
        "how",
        "this",
        "that",
        "what",
        "why",
        "espn",
        "into",
        "next",
        "year",
        "years",
        "latest",
        "best",
        "after",
    }
    words = []
    for row in rows:
        title = row.get("标题", "").lower()
        words.extend(word for word in re.findall(r"[a-zA-Z]{3,}", title) if word not in stopwords)
    labels, values = zip(*Counter(words).most_common(12))

    plt.figure(figsize=(10, 6))
    plt.barh(labels[::-1], values[::-1], color="#8b5cf6")
    plt.title("新闻标题高频关键词")
    plt.xlabel("出现次数")
    plt.ylabel("关键词")
    plt.tight_layout()
    output = OUTPUT_DIR / "图4_标题高频关键词.png"
    plt.savefig(output, dpi=180)
    plt.close()
    return output


def summarize(rows, chart_paths):
    times = [parse_news_time(row.get("时间", "")) for row in rows]
    valid_times = [dt for dt in times if dt is not None]
    lengths = [content_length(row) for row in rows]
    type_counts = Counter(infer_sport_type(row) for row in rows)

    print(f"读取新闻数量：{len(rows)}")
    print(f"平均正文长度：{sum(lengths) / len(lengths):.1f} 字符")
    print(f"最长正文长度：{max(lengths)} 字符")
    print(f"最短正文长度：{min(lengths)} 字符")
    if valid_times:
        print(f"时间范围：{min(valid_times)} 至 {max(valid_times)}")
    print("类别分布：")
    for label, count in type_counts.most_common():
        print(f"  {label}: {count}")
    print("生成图表：")
    for path in chart_paths:
        print(f"  {path.resolve()}")


def main():
    if not INPUT_XLSX.exists():
        raise FileNotFoundError(f"未找到输入文件：{INPUT_XLSX}")

    OUTPUT_DIR.mkdir(exist_ok=True)
    setup_chinese_font()

    rows = read_inline_xlsx(INPUT_XLSX)
    chart_paths = [
        save_sport_type_chart(rows),
        save_content_length_chart(rows),
        save_time_distribution_chart(rows),
        save_top_keywords_chart(rows),
    ]
    summarize(rows, chart_paths)


if __name__ == "__main__":
    main()
